window.QUIZ_REG = window.QUIZ_REG || {};
window.QUIZ_REG["Aptis_Listening_Part1.5"] = {"slug": "Aptis_Listening_Part1.5", "title": "APTIS LISTENING PART 1 – ĐỀ 05 (50 câu)", "items": [{"id": 1, "question": "A woman is talking to a shop assistant. Why does the woman return the dress?", "options": [{"key": "A", "text": "Because of its size"}, {"key": "B", "text": "Because of its color"}, {"key": "C", "text": "Because of its pattern"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q202.mp3", "transcript": "I'd like to return this dress please the pattern is really beautiful and I love it the color is a bit unusual for me but it looks nice when I wear it the main issue is the size it's too small I hope to lose weight but I don't think I can do it in time I just bought it yesterday so I hope the return process is easy", "translation": "Tôi muốn trả lại chiếc váy này, làm ơn, mẫu rất đẹp và tôi thích nó, màu sắc hơi khác thường đối với tôi nhưng nó trông rất đẹp khi tôi mặc nó, vấn đề chính là kích thước của nó quá nhỏ. Tôi hy vọng sẽ giảm cân nhưng tôi không nghĩ mình có thể làm kịp. Tôi mới mua nó hôm qua nên tôi hy vọng quá trình trả lại sẽ dễ dàng", "question_vi": "Một người phụ nữ đang nói chuyện với nhân viên bán hàng. Tại sao người phụ nữ trả lại chiếc váy?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q01.mp3"}, {"id": 2, "question": "Tom is talking with his friend about his teachers. Who is his favourite teacher?", "options": [{"key": "A", "text": "Miss Taylor"}, {"key": "B", "text": "Mr. Styles"}, {"key": "C", "text": "Miss Brown"}], "answer": "C", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q203.mp3", "transcript": "This semester I'm in Miss Taylor's class she's a new teacher so I'm still getting to know her style I've heard great things but I really miss Miss Brown she was my favorite teacher Miss Brown was so engaging and made learning fun I'm like Mr styles who is quite strict Miss Brown always encouraged us to ask questions and express ourselves I hope Ms Taylor will be just as inspiring", "translation": "Học kỳ này tôi đang học trong lớp của cô Taylor cô ấy là giáo viên mới nên tôi vẫn đang làm quen với phong cách của cô ấy Tôi đã nghe những điều tuyệt vời nhưng tôi thực sự nhớ cô Brown cô ấy là giáo viên yêu thích của tôi cô Brown rất lôi cuốn và làm cho việc học trở nên thú vị Tôi giống như Mr Styles, người khá nghiêm khắc cô Brown luôn khuyến khích chúng tôi đặt câu hỏi và thể hiện bản thân. Tôi hy vọng cô Taylor cũng sẽ truyền cảm hứng như vậy", "question_vi": "Tom đang nói chuyện với bạn của anh ấy về giáo viên của anh ấy. Giáo viên yêu thích của anh ấy là ai?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q02.mp3"}, {"id": 3, "question": "A woman is talking to the police. What did she lose?", "options": [{"key": "A", "text": "A necklace"}, {"key": "B", "text": "A bag"}, {"key": "C", "text": "A wallet"}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q204.mp3", "transcript": "I need to report a loss I went shopping for jewelry to buy a necklace for my friend's wedding afterward I took the 7:30 p.m. train home and realized I left my bag on the seat thankfully I was holding my wallet so I still have that the bag had some important items in it and I really hope to find it", "translation": "Tôi cần báo lỗ. Tôi đi mua đồ trang sức để mua một chiếc vòng cổ cho đám cưới của bạn tôi. Sau đó, tôi mất lúc 7 giờ 30 tối. tàu về nhà và nhận ra rằng tôi đã để túi trên ghế, may mắn thay, tôi đang cầm ví nên tôi vẫn còn giữ một số vật dụng quan trọng trong đó và tôi thực sự hy vọng tìm thấy nó", "question_vi": "Một người phụ nữ đang nói chuyện với cảnh sát. Cô ấy đã mất gì?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q03.mp3"}, {"id": 4, "question": "A man is talking to his friend. Why does he choose to be a doctor?", "options": [{"key": "A", "text": "To help people"}, {"key": "B", "text": "To make his family proud"}, {"key": "C", "text": "To make a lot of money"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q205.mp3", "transcript": "I've always wanted to be a doctor it's fulfilling to know that I can make a difference in someone's life my family is also proud of this career choice and they have encouraged me along the way some friends say doctors earn a lot of money which is a nice bonus but my main goal remains to save lives and provide care to those who need it most", "translation": "Tôi luôn muốn trở thành bác sĩ, thật vui khi biết rằng tôi có thể tạo ra sự khác biệt trong cuộc sống của ai đó, gia đình tôi cũng tự hào về sự lựa chọn nghề nghiệp này và họ đã động viên tôi trong suốt chặng đường. Một số bạn bè nói rằng bác sĩ kiếm được rất nhiều tiền, đó là một phần thưởng tuyệt vời nhưng mục tiêu chính của tôi vẫn là cứu sống và chăm sóc cho những người cần nó nhất", "question_vi": "Một người đàn ông đang nói chuyện với bạn mình. Tại sao anh ấy lại chọn làm bác sĩ?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q04.mp3"}, {"id": 5, "question": "David is in an interview. What was his last job?", "options": [{"key": "A", "text": "An engineer"}, {"key": "B", "text": "Teacher"}, {"key": "C", "text": "An electrician"}], "answer": "C", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q206.mp3", "transcript": "I studied Engineering in school but after graduation I decided to pursue a different path I found a teaching position that was very rewarding as I enjoyed sharing knowledge with students however I eventually transitioned to working as an electrician which has allowed me to apply my technical skills in a hands on way this job has been a great fit for me", "translation": "Tôi học ngành Kỹ thuật ở trường nhưng sau khi tốt nghiệp, tôi quyết định theo đuổi một con đường khác. Tôi tìm được một vị trí giảng dạy rất bổ ích vì tôi thích chia sẻ kiến ​​thức với sinh viên. Tuy nhiên, cuối cùng tôi đã chuyển sang làm thợ điện, điều này cho phép tôi áp dụng các kỹ năng kỹ thuật của mình vào thực tế, công việc này rất phù hợp với tôi", "question_vi": "David đang trong một cuộc phỏng vấn. Công việc cuối cùng của anh ấy là gì?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q05.mp3"}, {"id": 6, "question": "A tour guide is introducing a famous building. What is this building currently used for?", "options": [{"key": "A", "text": "A museum"}, {"key": "B", "text": "A department store"}, {"key": "C", "text": "A cinema"}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q207.mp3", "transcript": "Welcome everyone today I'd like to introduce you to this iconic building originally built in the 1920s it served as a museum until 1940 after World War II it was transformed into a cinema showcasing films for the public today this beautiful structure is now a bustling department store offering a wide range of products", "translation": "Chào mừng mọi người hôm nay tôi muốn giới thiệu với các bạn tòa nhà mang tính biểu tượng này ban đầu được xây dựng vào những năm 1920, nó được dùng làm bảo tàng cho đến năm 1940 sau Thế chiến thứ hai, nó được chuyển thành rạp chiếu phim chiếu phim cho công chúng ngày nay, công trình kiến ​​trúc xinh đẹp này hiện là một cửa hàng bách hóa nhộn nhịp cung cấp nhiều loại sản phẩm", "question_vi": "Hướng dẫn viên du lịch đang giới thiệu một tòa nhà nổi tiếng. Tòa nhà này hiện đang được sử dụng để làm gì?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q06.mp3"}, {"id": 7, "question": "A saleswoman is talking to her customer. How much is the cheapest computer in the shop?", "options": [{"key": "A", "text": "135 pounds"}, {"key": "B", "text": "145 pounds"}, {"key": "C", "text": "155 pounds"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q208.mp3", "transcript": "So we have several options for your computer the one priced at $145 is great for light gaming and everyday use if you need something more powerful for complex tasks I recommend the 155 lb model which offers better performance however if you're looking for something basic for simple tasks the cheapest option at 135 lb would be perfect", "translation": "Vì vậy, chúng tôi có một số tùy chọn cho máy tính của bạn, loại có giá $145 rất phù hợp để chơi game nhẹ và sử dụng hàng ngày nếu bạn cần thứ gì đó mạnh hơn cho các tác vụ phức tạp. Tôi khuyên dùng mẫu 155 lb mang lại hiệu suất tốt hơn tuy nhiên nếu bạn đang tìm kiếm thứ gì đó cơ bản cho các tác vụ đơn giản thì tùy chọn rẻ nhất ở mức 135 lb sẽ là hoàn hảo", "question_vi": "Một nhân viên bán hàng đang nói chuyện với khách hàng của mình. Máy tính rẻ nhất ở cửa hàng giá bao nhiêu?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q07.mp3"}, {"id": 8, "question": "Dan is going to university. Where should Dan turn right?", "options": [{"key": "A", "text": "At the Main Street"}, {"key": "B", "text": "At the hospital"}, {"key": "C", "text": "At the traffic lights"}], "answer": "C", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q209.mp3", "transcript": "Hey today is my first day at University and I want to make sure I'm on the right route first I'll go straight to Main Street after that I need to turn left at the hospital I've heard that the university is not far from there once I reach the traffic lights I'll turn right and I should be able to see the compass soon is that the correct way", "translation": "Này, hôm nay là ngày đầu tiên của tôi ở trường Đại học và tôi muốn chắc chắn rằng mình đi đúng đường trước tiên. Tôi sẽ đi thẳng đến Main Street sau đó tôi cần rẽ trái ở bệnh viện. Tôi nghe nói rằng trường đại học cách đó không xa khi tôi đến chỗ đèn giao thông, tôi sẽ rẽ phải và tôi sẽ sớm nhìn thấy la bàn. Đó có phải là cách chính xác không?", "question_vi": "Dan sắp vào đại học. Dan nên rẽ phải ở đâu?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q08.mp3"}, {"id": 9, "question": "A man is calling his friend. Where will they meet?", "options": [{"key": "A", "text": "At school"}, {"key": "B", "text": "By the park"}, {"key": "C", "text": "In the cafe"}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q210.mp3", "transcript": "After finishing my classes at school I wanted to ask if you'd like to meet up how about we go to a cafe it's a nice spot but to be honest we often end up there I thought it might be refreshing to change things up a bit how about we meet by the park instead we can enjoy the fresh air and maybe take a walk what do you think", "translation": "Sau khi học xong ở trường, tôi muốn hỏi xem bạn có muốn gặp nhau không. Chúng ta đến quán cà phê nhé, đó là một địa điểm đẹp nhưng thành thật mà nói thì chúng ta thường đến đó. Tôi nghĩ sẽ thú vị hơn nếu thay đổi mọi thứ một chút. Hay chúng ta gặp nhau ở công viên thay vì chúng ta có thể tận hưởng không khí trong lành và có thể đi dạo bạn nghĩ sao?", "question_vi": "Một người đàn ông đang gọi cho bạn mình. Họ sẽ gặp nhau ở đâu?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q09.mp3"}, {"id": 10, "question": "A man is calling his mother. How long will he be late?", "options": [{"key": "A", "text": "10 minutes"}, {"key": "B", "text": "15 minutes"}, {"key": "C", "text": "20 minutes"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q211.mp3", "transcript": "Hi Mom it's me I'm stuck in traffic right now so I'll be late the train takes about 20 minutes but I'll arrive 10 minutes late don't worry though we still have 15 minutes until our appointment with Mr Smith I'll hurry as much as I can I just wanted to let you know so you're not waiting too long", "translation": "Xin chào mẹ, con là con. Hiện tại con đang bị kẹt xe nên con sẽ trễ chuyến tàu mất khoảng 20 phút nhưng con sẽ đến muộn 10 phút, đừng lo lắng mặc dù chúng ta vẫn còn 15 phút cho đến cuộc hẹn với ông Smith. Con sẽ nhanh nhất có thể. Con chỉ muốn thông báo cho mẹ biết để mẹ không phải đợi quá lâu", "question_vi": "Một người đàn ông đang gọi mẹ mình. Anh ấy sẽ đến muộn bao lâu?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q10.mp3"}, {"id": 11, "question": "A woman is going to the cinema with her husband. What time does the movie begin?", "options": [{"key": "A", "text": "6:40"}, {"key": "B", "text": "7:00"}, {"key": "C", "text": "9:20"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q212.mp3", "transcript": "I just checked the movie schedule and the film actually begins at 6:40 not at 7:00 like I thought after the movie we'll finish around 9:20 do you want to grab something to eat afterwards we can go to that new restaurant nearby and relax after the movie it'll be nice to talk about the film while enjoying a meal together", "translation": "Tôi vừa kiểm tra lịch chiếu phim và bộ phim thực sự bắt đầu lúc 6:40 chứ không phải lúc 7:00 như tôi nghĩ sau bộ phim chúng ta sẽ kết thúc vào khoảng 9:20 bạn có muốn ăn gì đó sau đó chúng ta có thể đến nhà hàng mới gần đó và thư giãn sau bộ phim. Thật tuyệt khi cùng nhau trò chuyện về bộ phim trong khi thưởng thức bữa ăn", "question_vi": "Một người phụ nữ đi xem phim cùng chồng. Phim bắt đầu lúc mấy giờ?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q11.mp3"}, {"id": 12, "question": "A teacher is talking to her students. Where are the students now?", "options": [{"key": "A", "text": "At school"}, {"key": "B", "text": "In a townhouse"}, {"key": "C", "text": "In a museum"}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q213.mp3", "transcript": "I'm so glad we decided to take this field trip it's a great way to learn about history in a more interactive way I know some of you were hoping we could visit the museum instead but I think this townhouse trip is a more unique experience it is also near our school which is more convenient for you I hope you're all enjoying yourselves and learning a lot today", "translation": "Tôi rất vui vì chúng ta đã quyết định thực hiện chuyến đi thực địa này. Đây là một cách tuyệt vời để tìm hiểu về lịch sử theo cách tương tác hơn. Tôi biết một số bạn đang hy vọng chúng ta có thể đến thăm bảo tàng nhưng tôi nghĩ chuyến đi tại nhà phố này là một trải nghiệm độc đáo hơn. Nó cũng ở gần trường học của chúng tôi, thuận tiện hơn cho các bạn. Tôi hy vọng các bạn sẽ tận hưởng và học hỏi được nhiều điều hôm nay", "question_vi": "Một giáo viên đang nói chuyện với học sinh của mình. Bây giờ học sinh ở đâu?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q12.mp3"}, {"id": 13, "question": "Louis is having dinner in a new restaurant. What is his opinion about that restaurant?", "options": [{"key": "A", "text": "The price is cheap"}, {"key": "B", "text": "The food is delicious"}, {"key": "C", "text": "The service is slow"}], "answer": "C", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q214.mp3", "transcript": "I'm not impressed with this new restaurant honestly we shouldn't have chosen to eat here the prices are high and I'm not even sure if the food is good or not but what really bothers me is the slow service it's taking forever to get our orders it's been 25 minutes and I'm so hungry", "translation": "Thành thật mà nói, tôi không ấn tượng với nhà hàng mới này, lẽ ra chúng tôi không nên chọn ăn ở đây. Giá cao và tôi thậm chí không chắc đồ ăn có ngon hay không nhưng điều thực sự làm tôi khó chịu là dịch vụ chậm chạp, phải mất mãi mãi mới nhận được đơn đặt hàng của chúng tôi. Đã 25 phút và tôi rất đói", "question_vi": "Louis đang ăn tối ở một nhà hàng mới. Ý kiến ​​của anh ấy về nhà hàng đó là gì?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q13.mp3"}, {"id": 14, "question": "Which room is the class in?", "options": [{"key": "A", "text": "201"}, {"key": "B", "text": "301"}, {"key": "C", "text": "103"}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q215.mp3", "transcript": "Excuse me I'm looking for the English class I remember it used to be in room 2017 but I'm not sure if it's still there someone also mentioned room 103 so I'm a bit confused yeah they changed the schedule recently so it's no longer in either of those rooms it's now on the third floor in room 301", "translation": "Xin lỗi, tôi đang tìm lớp học tiếng Anh. Tôi nhớ nó từng ở trong phòng năm 2017 nhưng tôi không chắc liệu nó có còn ở đó không. Có người cũng nhắc đến phòng 103 nên tôi hơi bối rối vâng, họ đã thay đổi lịch gần đây nên không còn ở một trong hai phòng đó nữa, giờ nó ở trên tầng ba trong phòng 301", "question_vi": "Lớp học ở phòng nào?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q14.mp3"}, {"id": 15, "question": "An artist is talking about her job. What is unique about her job?", "options": [{"key": "A", "text": "She works from 9 to 5"}, {"key": "B", "text": "She doesn't work on weekends"}, {"key": "C", "text": "She works irregular hours"}], "answer": "C", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q216.mp3", "transcript": "I'm an artist so my work is quite different from most jobs I don't have a fixed schedule and I don't work the same hours every day sometimes I work a lot and sometimes I don't work much it really depends on how I feel and my ideas", "translation": "Tôi là một nghệ sĩ nên công việc của tôi khá khác biệt so với hầu hết các công việc. Tôi không có lịch trình cố định và tôi không làm việc theo giờ cố định mỗi ngày, đôi khi tôi làm việc rất nhiều và đôi khi tôi làm việc không nhiều, điều đó thực sự phụ thuộc vào cảm giác và ý tưởng của tôi", "question_vi": "Một nghệ sĩ đang nói về công việc của mình. Công việc của cô ấy có gì độc đáo?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q15.mp3"}, {"id": 16, "question": "Number of inhabitants in a countryside?", "options": [{"key": "A", "text": "10000"}, {"key": "B", "text": "1000"}, {"key": "C", "text": "100000"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q217.mp3", "transcript": "This Countryside area has a population of around 10,000 people most residents work in farming or run small local businesses in recent years the area has developed slowly but it still keeps its traditional and peaceful way of life many visitors come here to enjoy the natural surroundings and the quiet atmosphere", "translation": "Khu vực nông thôn này có dân số khoảng 10.000 người, hầu hết cư dân làm nông nghiệp hoặc điều hành các doanh nghiệp nhỏ ở địa phương trong những năm gần đây, khu vực này phát triển chậm nhưng vẫn giữ lối sống truyền thống và yên bình. Nhiều du khách đến đây để tận hưởng khung cảnh thiên nhiên và bầu không khí yên tĩnh", "question_vi": "Số dân ở một vùng nông thôn?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q16.mp3"}, {"id": 17, "question": "What time will I see you?", "options": [{"key": "A", "text": "6h30"}, {"key": "B", "text": "6h00"}, {"key": "C", "text": "3h30"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q218.mp3", "transcript": "What time will I see you tomorrow I was thinking we could meet at 6:00 or maybe even a bit earlier if that works better for you I won't be free that early because I finish work at 6:00 so it's better if we meet a little later around 6:30", "translation": "Ngày mai tôi sẽ gặp bạn lúc mấy giờ Tôi đang nghĩ chúng ta có thể gặp nhau lúc 6:00 hoặc thậm chí sớm hơn một chút nếu điều đó tốt hơn cho bạn Tôi sẽ không rảnh sớm như vậy vì tôi tan làm lúc 6:00 nên sẽ tốt hơn nếu chúng ta gặp nhau muộn hơn một chút vào khoảng 6:30", "question_vi": "Tôi sẽ gặp bạn lúc mấy giờ?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q17.mp3"}, {"id": 18, "question": "Two people buy something together?", "options": [{"key": "A", "text": "Trousers"}, {"key": "B", "text": "Shorts"}, {"key": "C", "text": "Shirt"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q219.mp3", "transcript": "I want to buy some new clothes today I was thinking about getting a shirt or maybe a pair of shorts because the weather is getting warmer that sounds good but I actually need some trousers for work and since we're shopping together let's just buy those fine I'll buy a pair too", "translation": "Hôm nay tôi muốn mua một số quần áo mới. Tôi đang nghĩ đến việc mua một chiếc áo sơ mi hoặc có thể là một chiếc quần đùi vì thời tiết đang ấm hơn, điều đó nghe có vẻ hay nhưng tôi thực sự cần một số quần dài để đi làm và vì chúng ta đang đi mua sắm cùng nhau nên hãy mua những thứ đó tốt nhé. Tôi cũng sẽ mua một chiếc", "question_vi": "Hai người cùng nhau mua cái gì?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q18.mp3"}, {"id": 19, "question": "What will she do?", "options": [{"key": "A", "text": "Go to the cinema"}, {"key": "B", "text": "Go camping"}, {"key": "C", "text": "Go for a drive"}], "answer": "C", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q220.mp3", "transcript": "I was thinking about going to the cinema this weekend because there's a new film I really want to see I also considered going camping but the weather doesn't look very good in the end I think I'll just go for a drive and relax a bit instead", "translation": "Tôi đang nghĩ đến việc đi xem phim vào cuối tuần này vì có một bộ phim mới mà tôi rất muốn xem. Tôi cũng đang cân nhắc việc đi cắm trại nhưng cuối cùng thì thời tiết có vẻ không được tốt lắm. Tôi nghĩ tôi sẽ lái xe đi và thư giãn một chút.", "question_vi": "Cô ấy sẽ làm gì?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q19.mp3"}, {"id": 20, "question": "How much do eggs cost?", "options": [{"key": "A", "text": "1.50 pounds"}, {"key": "B", "text": "1.60 pounds"}, {"key": "C", "text": "1.70 pounds"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q221.mp3", "transcript": "I went to the market this morning to buy some food I saw that some items were quite expensive like milk and bread then I checked the price of eggs at first I thought they were 1 lb 70 50 which is much better", "translation": "Sáng nay tôi đi chợ mua đồ ăn. Tôi thấy một số mặt hàng khá đắt như sữa và bánh mì, sau đó tôi kiểm tra giá trứng lúc đầu tôi nghĩ là 1 lb 70 50, tốt hơn nhiều", "question_vi": "Trứng giá bao nhiêu?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q20.mp3"}, {"id": 21, "question": "What are the main activities taking place this weekend?", "options": [{"key": "A", "text": "Camping"}, {"key": "B", "text": "They go swimming"}, {"key": "C", "text": "They walk together"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q222.mp3", "transcript": "This weekend we are planning what to do together last holiday we went camping in the countryside and we really enjoyed it we sometimes go swimming or take a walk but this weekend we don't want to do those usual activities since last year's activities were great we've decided to go camping again", "translation": "Cuối tuần này chúng tôi đang lên kế hoạch làm gì cùng nhau vào kỳ nghỉ trước, chúng tôi đã đi cắm trại ở vùng nông thôn và chúng tôi thực sự rất thích nó, đôi khi chúng tôi đi bơi hoặc đi dạo nhưng cuối tuần này chúng tôi không muốn thực hiện những hoạt động thường ngày đó vì các hoạt động năm ngoái rất tuyệt nên chúng tôi đã quyết định đi cắm trại lần nữa", "question_vi": "Các hoạt động chính diễn ra cuối tuần này là gì?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q21.mp3"}, {"id": 22, "question": "What color do you like?", "options": [{"key": "A", "text": "Red"}, {"key": "B", "text": "White"}, {"key": "C", "text": "Blue"}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q223.mp3", "transcript": "What color do you like I really like bright colors like red and blue because they look more interesting but some people prefer something simpler I see what you mean but I don't really like strong colors I prefer white because it looks clean and easy to match with other things", "translation": "Bạn thích màu gì Tôi thực sự thích những màu sáng như đỏ và xanh vì chúng trông thú vị hơn nhưng một số người thích thứ gì đó đơn giản hơn Tôi hiểu ý bạn nhưng tôi không thực sự thích những màu mạnh Tôi thích màu trắng vì nó trông sạch sẽ và dễ kết hợp với những thứ khác", "question_vi": "Bạn thích màu gì?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q22.mp3"}, {"id": 23, "question": "Harvest", "options": [{"key": "A", "text": "2.50 pounds"}, {"key": "B", "text": "2.90 pounds"}, {"key": "C", "text": "3.50 pounds"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q224.mp3", "transcript": "During the harvest season Farmers sell a lot of fresh products at the local market I was checking the prices yesterday and I saw that some items were quite expensive at first I thought the price was $3.50 but that was for a different product then I looked again and saw that it actually cost 2 lbs 50 which was much cheaper", "translation": "Trong mùa thu hoạch Nông dân bán rất nhiều sản phẩm tươi sống ở chợ địa phương Tôi đã kiểm tra giá ngày hôm qua và thấy một số mặt hàng khá đắt. Lúc đầu tôi nghĩ giá là 3,50 đô la nhưng đó là cho một sản phẩm khác, sau đó tôi nhìn lại và thấy rằng nó thực sự có giá 2 lbs 50, rẻ hơn nhiều", "question_vi": "Mùa gặt", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q23.mp3"}, {"id": 24, "question": "You are going to Edinburgh by train. Which platform should you go to?", "options": [{"key": "A", "text": "Two"}, {"key": "B", "text": "Three"}, {"key": "C", "text": "Four"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q225.mp3", "transcript": "Excuse me which door should I take to go to Edinburgh I saw Doors 3 and 4 over there so I'm a bit confused yes I understand but those doors are for other trains you need to go through door two to catch the train to Edinburgh", "translation": "Xin lỗi, tôi nên đi cửa nào để đến Edinburgh. Tôi thấy Cửa 3 và 4 ở đó nên tôi hơi bối rối, vâng, tôi hiểu nhưng những cánh cửa đó dành cho các chuyến tàu khác, bạn cần đi qua cửa số hai để bắt chuyến tàu đến Edinburgh", "question_vi": "Bạn sẽ đến Edinburgh bằng tàu hỏa. Bạn nên truy cập nền tảng nào?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q24.mp3"}, {"id": 25, "question": "Where do you usually go when you travel?", "options": [{"key": "A", "text": "Go to the park"}, {"key": "B", "text": "Go to the swimming pool"}, {"key": "C", "text": "Go to the restaurant"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q226.mp3", "transcript": "Some people prefer going to restaurants or swimming pools but I don't usually do those things instead I often go to the park walk around and enjoy the fresh air", "translation": "Một số người thích đến nhà hàng hoặc bể bơi nhưng tôi thường không làm những việc đó thay vào đó tôi thường đến công viên đi dạo và tận hưởng không khí trong lành", "question_vi": "Bạn thường đi đâu khi đi du lịch?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q25.mp3"}, {"id": 26, "question": "Where to hold the event?", "options": [{"key": "A", "text": "Outside"}, {"key": "B", "text": "Market"}, {"key": "C", "text": "School"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q227.mp3", "transcript": "We need to decide where to hold the event I was thinking about having it at the market or maybe at the school hall because they have enough facilities for everyone that's a good point but I think it would be much better to have it outside especially if the weather is nice everyone can enjoy the fresh air and it will be more convenient to hold activities okay that sounds great to me too let's hold the event outside", "translation": "Chúng ta cần quyết định địa điểm tổ chức sự kiện. Tôi đang nghĩ đến việc tổ chức nó ở chợ hoặc có thể ở hội trường vì họ có đủ cơ sở vật chất cho mọi người, đó là một điểm tốt nhưng tôi nghĩ sẽ tốt hơn nếu tổ chức sự kiện ở bên ngoài, đặc biệt nếu thời tiết đẹp thì mọi người có thể tận hưởng không khí trong lành và sẽ thuận tiện hơn khi tổ chức các hoạt động. Được rồi, tôi cũng nghĩ vậy, hãy tổ chức sự kiện bên ngoài", "question_vi": "Tổ chức sự kiện ở đâu?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q26.mp3"}, {"id": 27, "question": "Where did they meet?", "options": [{"key": "A", "text": "The parking lot"}, {"key": "B", "text": "The front entrance"}, {"key": "C", "text": "The school gate"}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q228.mp3", "transcript": "Where did we meet yesterday was it at the parking lot or near the school gate I can't remember clearly know it wasn't either of those we met at the front entrance before going inside", "translation": "Hôm qua chúng ta đã gặp nhau ở đâu là ở bãi đậu xe hay gần cổng trường Tôi không thể nhớ rõ rằng đó không phải là một trong những người chúng tôi đã gặp ở cổng trước trước khi vào trong", "question_vi": "Họ đã gặp nhau ở đâu?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q27.mp3"}, {"id": 28, "question": "Which country will they study next semester?", "options": [{"key": "A", "text": "France"}, {"key": "B", "text": "Germany"}, {"key": "C", "text": "Italy"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q229.mp3", "transcript": "Next semester I'm planning to study abroad at first I thought about going to Germany or Italy because they both have great universities interested in", "translation": "Học kỳ tới tôi dự định đi du học Lúc đầu tôi nghĩ đến việc đi Đức hoặc Ý vì cả hai đều có những trường đại học lớn quan tâm đến", "question_vi": "Họ sẽ học ở nước nào trong học kỳ tiếp theo?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q28.mp3"}, {"id": 29, "question": "You want to buy a new computer. Which button on your phone should you press?", "options": [{"key": "A", "text": "One"}, {"key": "B", "text": "Two"}, {"key": "C", "text": "Three"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q230.mp3", "transcript": "Welcome to tech store customer services if you are calling about a computer you have already bought press two if you need help with a phone or tablet press 3 if you would like to buy a new computer please press one", "translation": "Chào mừng bạn đến với dịch vụ khách hàng của cửa hàng công nghệ nếu bạn gọi điện về một chiếc máy tính bạn đã mua, hãy nhấn phím hai nếu bạn cần trợ giúp về điện thoại hoặc máy tính bảng, hãy nhấn phím 3 nếu bạn muốn mua một máy tính mới, vui lòng nhấn phím một", "question_vi": "Bạn muốn mua một chiếc máy tính mới. Bạn nên nhấn nút nào trên điện thoại?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q29.mp3"}, {"id": 30, "question": "Listen to the phone message about a meeting. What does John want Ruth to do?", "options": [{"key": "A", "text": "Have the meeting without him"}, {"key": "B", "text": "Cancel the meeting"}, {"key": "C", "text": "Wait for him"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q231.mp3", "transcript": "Hi Ruth it's John I'm sorry but I'm stuck in traffic and I don't think I'll get to the office in time for the meeting please don't wait for me I know we talked about canceling it if someone couldn't come but I think the meeting is important and should go ahead as I'll read the notes later thanks", "translation": "Xin chào Ruth, John, tôi xin lỗi nhưng tôi bị kẹt xe và tôi không nghĩ mình sẽ đến văn phòng kịp cuộc họp, xin đừng đợi tôi. Tôi biết chúng ta đã bàn về việc hủy cuộc họp nếu ai đó không thể đến nhưng tôi nghĩ cuộc họp rất quan trọng và nên tiếp tục vì tôi sẽ đọc ghi chú sau, cảm ơn", "question_vi": "Nghe tin nhắn điện thoại về một cuộc họp. John muốn Ruth làm gì?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q30.mp3"}, {"id": 31, "question": "Listen to Mary talking to her friends. What does she ask them about?", "options": [{"key": "A", "text": "Where the supermarket is"}, {"key": "B", "text": "How to set up the bedroom"}, {"key": "C", "text": "Where to buy a new table"}], "answer": "C", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q232.mp3", "transcript": "Hi Ivan it's Mary I just moved into my new house I want something nice for the dining area I also saw a cute coffee shop nearby and I'm thinking about getting a mirror for the living room I need to get some furniture especially a coffee table do you know where to buy one", "translation": "Xin chào Ivan, tôi là Mary. Tôi mới chuyển đến ngôi nhà mới của mình. Tôi muốn một cái gì đó đẹp đẽ cho khu vực ăn uống. Tôi cũng thấy một quán cà phê dễ thương gần đó và tôi đang nghĩ đến việc mua một chiếc gương cho phòng khách. Tôi cần một số đồ nội thất, đặc biệt là một bàn cà phê, bạn có biết mua ở đâu không?", "question_vi": "Hãy nghe Mary nói chuyện với bạn bè của cô ấy. Cô ấy hỏi họ về điều gì?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q31.mp3"}, {"id": 32, "question": "Listen to a man talk about weekends. What does his family do most weekends?", "options": [{"key": "A", "text": "Goes to the park"}, {"key": "B", "text": "Goes to the mountains"}, {"key": "C", "text": "Goes to the city"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q233.mp3", "transcript": "Hello everyone I want to share what my family usually does on weekends we love spending time together and often go for a walk in the park it's a nice way to relax and enjoy nature we like to see the flowers and sometimes have a picnic however this weekend is different my sister is visiting us and we have planned a small family gathering at home we will cook a big meal together and play some games it will be fun to catch up and spend quality time as a family I'm really looking forward to it", "translation": "Xin chào mọi người Tôi muốn chia sẻ những gì gia đình tôi thường làm vào cuối tuần, chúng tôi thích dành thời gian cùng nhau và thường đi dạo trong công viên, đó là một cách hay để thư giãn và tận hưởng thiên nhiên, chúng tôi thích ngắm hoa và đôi khi đi dã ngoại, tuy nhiên cuối tuần này thì khác, chị gái tôi đến thăm chúng tôi và chúng tôi đã lên kế hoạch cho một buổi họp mặt gia đình nhỏ tại nhà, chúng tôi sẽ cùng nhau nấu một bữa ăn lớn và chơi một số trò chơi, sẽ rất vui nếu được cùng nhau trò chuyện và dành thời gian chất lượng như một gia đình. Tôi thực sự mong chờ điều đó", "question_vi": "Hãy nghe một người đàn ông nói về những ngày cuối tuần. Gia đình anh ấy làm gì vào hầu hết các ngày cuối tuần?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q32.mp3"}, {"id": 33, "question": "A tour leader is giving information. Where will the group wait for the bus?", "options": [{"key": "A", "text": "By the hotel's side entrance"}, {"key": "B", "text": "Behind the hotel"}, {"key": "C", "text": "By the hotel's main entrance"}], "answer": "C", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q234.mp3", "transcript": "Good morning everyone let me walk you through today's schedule first will start the day at 9 a.m. with a visit to the city museum where you'll have about 2 hours to explore the exhibits after that at 12:30 p.m. will head to the Central Park for a picnic lunch and a relaxing stroll around 3:00 p.m. will make our way to the Old Town Market where you can shop for souvenirs and enjoy some local treats will wrap up our activities by 6:00 p.m. giving you a little free time back at the hotel finally at 8:00 p.m. will meet at the hotels main entrance to catch the bus to the airport make sure to be on time and we'll head to the airport together", "translation": "Chào buổi sáng mọi người, hãy để tôi hướng dẫn bạn lịch trình ngày hôm nay. Đầu tiên, ngày mới sẽ bắt đầu lúc 9 giờ sáng với chuyến tham quan bảo tàng thành phố, nơi bạn sẽ có khoảng 2 giờ để khám phá các cuộc triển lãm sau đó lúc 12:30 trưa. sẽ đến Công viên Trung tâm để ăn trưa dã ngoại và đi dạo thư giãn vào khoảng 3 giờ chiều. sẽ đến Chợ Phố Cổ, nơi bạn có thể mua quà lưu niệm và thưởng thức một số món ăn địa phương. Hoạt động của chúng tôi sẽ kết thúc trước 6 giờ chiều. cho bạn chút thời gian rảnh rỗi để quay lại khách sạn vào lúc 8 giờ tối. sẽ gặp nhau ở cổng chính của khách sạn để bắt xe buýt đến sân bay, đảm bảo đến đúng giờ và chúng ta sẽ cùng nhau đến sân bay", "question_vi": "Một trưởng đoàn du lịch đang cung cấp thông tin. Nhóm sẽ đợi xe buýt ở đâu?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q33.mp3"}, {"id": 34, "question": "Henry talks to his colleague about some clients. How many clients are American?", "options": [{"key": "A", "text": "Three"}, {"key": "B", "text": "One"}, {"key": "C", "text": "Five"}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q235.mp3", "transcript": "We need to prepare for tomorrow's meeting with our clients how many are coming 5 in total three are from Germany and one is from France and the last one is from the United States so we have one American client great thanks for letting me know", "translation": "Chúng tôi cần chuẩn bị cho cuộc gặp ngày mai với khách hàng của mình, có bao nhiêu người đến, tổng cộng 5 người đến từ Đức và một người đến từ Pháp và người cuối cùng đến từ Hoa Kỳ nên chúng tôi có một khách hàng người Mỹ. Cảm ơn vì đã cho tôi biết", "question_vi": "Henry nói chuyện với đồng nghiệp của mình về một số khách hàng. Có bao nhiêu khách hàng là người Mỹ?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q34.mp3"}, {"id": 35, "question": "A friend tells John how to drive to the station. How long does it take?", "options": [{"key": "A", "text": "40 minutes"}, {"key": "B", "text": "20 minutes"}, {"key": "C", "text": "30 minutes"}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q236.mp3", "transcript": "Hi John to get to the station just follow the main road and turn left at the traffic lights it usually takes about 20 minutes from here if the traffic is really bad it can take 30 minutes and once it even took me 40 minutes during rush hours but most of the time you'll get there in about 20 minutes", "translation": "Xin chào John, để đến nhà ga, bạn chỉ cần đi theo đường chính và rẽ trái tại đèn giao thông, từ đây thường mất khoảng 20 phút nếu giao thông rất tệ, có thể mất 30 phút và có lần tôi thậm chí còn mất 40 phút trong giờ cao điểm nhưng hầu hết thời gian bạn sẽ đến đó trong khoảng 20 phút", "question_vi": "Một người bạn chỉ cho John cách lái xe đến nhà ga. Phải mất bao lâu?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q35.mp3"}, {"id": 36, "question": "Listen to the message. Which room is the first class for the computer course in?", "options": [{"key": "A", "text": "Room 304"}, {"key": "B", "text": "Room 206"}, {"key": "C", "text": "Room 301"}], "answer": "C", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q237.mp3", "transcript": "Hello everyone this is a message for students on the computer course please note that some room numbers have changed room 206 is being used for a business class today and room 304 is closed for repairs this week your first computer class will be held in room 301 at 9:00 a.m. on Monday we look forward to seeing you there", "translation": "Xin chào mọi người, đây là tin nhắn dành cho sinh viên khóa học máy tính xin lưu ý rằng một số phòng đã thay đổi, phòng 206 đang được sử dụng cho hạng thương gia hôm nay và phòng 304 đóng cửa để sửa chữa trong tuần này, lớp học máy tính đầu tiên của bạn sẽ được tổ chức tại phòng 301 lúc 9:00 sáng thứ Hai, chúng tôi rất mong được gặp bạn ở đó", "question_vi": "Nghe tin nhắn. Phòng học đầu tiên của khóa học máy tính là phòng nào?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q36.mp3"}, {"id": 37, "question": "Listen to the announcement. Where will the people meet for the bus home?", "options": [{"key": "A", "text": "Marketplace"}, {"key": "B", "text": "Stadium"}, {"key": "C", "text": "Hotel"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q238.mp3", "transcript": "Attention everyone our trip will finish at 5:00 p.m. some of you are visiting the stadium this afternoon and Others May return to the hotel before then however the bus home will leave from the marketplace at 5:15 p.m. please make sure you are there on time", "translation": "Mọi người chú ý chuyến đi của chúng ta sẽ kết thúc lúc 5 giờ chiều. một số bạn sẽ đến thăm sân vận động chiều nay và những người khác có thể quay lại khách sạn trước đó tuy nhiên xe buýt về nhà sẽ rời chợ lúc 5:15 chiều. hãy chắc chắn rằng bạn có mặt đúng giờ", "question_vi": "Nghe thông báo. Mọi người sẽ gặp nhau ở đâu để bắt xe buýt về nhà?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q37.mp3"}, {"id": 38, "question": "There is a meeting with the clients. What time do they want the meeting?", "options": [{"key": "A", "text": "12.30 p.m."}, {"key": "B", "text": "2 p.m."}, {"key": "C", "text": "1.30 p.m."}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q239.mp3", "transcript": "Hi Sarah I spoke to the clients about tomorrow's meeting we first suggested half past 12:30 but they said that was too early then we asked if 1:30 would be suitable but they already had another appointment in the end they requested a meeting at 2:00 please update the schedule thanks", "translation": "Xin chào Sarah, tôi đã nói chuyện với khách hàng về cuộc họp ngày mai, đầu tiên chúng tôi đề xuất cuộc họp lúc 12:30 nhưng họ nói rằng còn quá sớm nên chúng tôi hỏi liệu 1:30 có phù hợp không nhưng cuối cùng họ đã có một cuộc hẹn khác. Họ yêu cầu một cuộc gặp lúc 2:00, vui lòng cập nhật lịch trình, cảm ơn", "question_vi": "Có cuộc họp với khách hàng. Họ muốn gặp lúc mấy giờ?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q38.mp3"}, {"id": 39, "question": "Listen to a brother and a sister at the sister's new flat. What does the man have to drink?", "options": [{"key": "A", "text": "Tea"}, {"key": "B", "text": "Water"}, {"key": "C", "text": "Coffee"}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q240.mp3", "transcript": "Welcome to my new flat would you like some tea or coffee I'd love a coffee but actually I've already had two today tea sounds good I'm afraid I've run out of tea so you'll have to have some water instead", "translation": "Chào mừng bạn đến căn hộ mới của tôi, bạn có muốn uống trà hay cà phê không? Tôi muốn một ly cà phê nhưng thực ra hôm nay tôi đã uống hai cốc trà rồi, nghe có vẻ ngon đấy. Tôi e rằng tôi đã hết trà nên thay vào đó bạn sẽ phải uống một ít nước", "question_vi": "Lắng nghe anh trai và em gái ở căn hộ mới của em gái. Người đàn ông phải uống gì?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q39.mp3"}, {"id": 40, "question": "A woman is calling her husband. What time is lunch going to be ready?", "options": [{"key": "A", "text": "2 p.m."}, {"key": "B", "text": "12:30 p.m."}, {"key": "C", "text": "1.15 p.m."}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q241.mp3", "transcript": "Hi are you nearly home I was hoping lunch would be ready by 12:30 sorry I'm running late I don't think I can start cooking until about 1:15 that's okay I'm driving home in around 1 hour can you please make lunch 2:00 then that's okay", "translation": "Xin chào, bạn gần về nhà chưa Tôi đã hy vọng bữa trưa sẽ sẵn sàng trước 12:30 xin lỗi, tôi đến muộn. Tôi không nghĩ mình có thể bắt đầu nấu ăn cho đến khoảng 1:15, không sao đâu. Tôi sẽ lái xe về nhà trong khoảng 1 giờ nữa. Bạn có thể làm bữa trưa lúc 2:00 được không?", "question_vi": "Một người phụ nữ đang gọi chồng mình. Bữa trưa sẽ sẵn sàng lúc mấy giờ?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q40.mp3"}, {"id": 41, "question": "What time do they meet?", "options": [{"key": "A", "text": "5.45 pm"}, {"key": "B", "text": "6.15 pm"}, {"key": "C", "text": "6.30 pm"}], "answer": "C", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q242.mp3", "transcript": "Shall we meet at a quarter to 6:00 I can't make it that early I finish work at 6:00 okay what about 6:10 I'd still be traveling then let's meet at half past 6:30 instead perfect see you then", "translation": "Chúng ta sẽ gặp nhau lúc 15h đến 6 giờ. Tôi không thể đến sớm như vậy. Tôi xong việc lúc 6:00 được rồi, còn 6:10 thì sao. Tôi vẫn đang đi du lịch, vậy thì hãy gặp nhau lúc 6:30 rưỡi nhé, thay vào đó, hẹn gặp bạn nhé", "question_vi": "Họ gặp nhau lúc mấy giờ?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q41.mp3"}, {"id": 42, "question": "What is her favorite thing to do in her spare time?", "options": [{"key": "A", "text": "Going to the theatre"}, {"key": "B", "text": "Go to the park"}, {"key": "C", "text": "Listen to music"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q243.mp3", "transcript": "I enjoy lots of different activities in my spare time when the weather is nice I often go to the park with my friends and I listen to music almost everyday however my favorite thing to do is going to the theater I love watching live performances whenever I get the chance", "translation": "Tôi thích nhiều hoạt động khác nhau vào thời gian rảnh rỗi khi thời tiết đẹp Tôi thường đi công viên với bạn bè và nghe nhạc hầu như hàng ngày tuy nhiên điều tôi thích làm nhất là đến rạp hát Tôi thích xem các buổi biểu diễn trực tiếp bất cứ khi nào có cơ hội", "question_vi": "Điều cô ấy thích làm trong thời gian rảnh rỗi là gì?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q42.mp3"}, {"id": 43, "question": "Maria is asking the receptionist about her class. What floor is the French class on?", "options": [{"key": "A", "text": "First floor"}, {"key": "B", "text": "Second floor"}, {"key": "C", "text": "Third floor"}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q244.mp3", "transcript": "Excuse me where is the French class is it on the first floor it used to be on the first floor but it was moved last week it's now on the second floor next to room 215 the third floor is only for computer classes", "translation": "Xin lỗi, lớp học tiếng Pháp ở đâu? Ở tầng một, trước đây nó ở tầng một nhưng nó đã được chuyển đi vào tuần trước, bây giờ nó ở tầng hai cạnh phòng 215, tầng ba chỉ dành cho lớp học máy tính", "question_vi": "Maria đang hỏi nhân viên lễ tân về lớp học của cô ấy. Lớp học tiếng Pháp ở tầng mấy?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q43.mp3"}, {"id": 44, "question": "How much does the cake cost?", "options": [{"key": "A", "text": "Three dollars twenty"}, {"key": "B", "text": "Five dollars twenty"}, {"key": "C", "text": "Two dollars twenty"}], "answer": "C", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q245.mp3", "transcript": "Excuse me how much is this cake it's normally $3.20 but it's on sale today after the discount it costs $2.20 the larger cake next to it is $5.20", "translation": "Xin lỗi, chiếc bánh này giá bao nhiêu, bình thường là $3,20 nhưng hôm nay nó được giảm giá, sau khi giảm giá, nó có giá $2,20, chiếc bánh lớn hơn bên cạnh là $5,20", "question_vi": "Bánh có giá bao nhiêu?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q44.mp3"}, {"id": 45, "question": "What does she think about the book?", "options": [{"key": "A", "text": "Interesting"}, {"key": "B", "text": "Boring"}, {"key": "C", "text": "Exciting"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/l/i/lis-p1-test-05-q246.mp3", "transcript": "How do you finish reading that book I lent you yes I finished it yesterday so was it exciting not really it wasn't exciting and it certainly wasn't boring either oh okay then what did you think of it I found it quite interesting I learned a lot from it", "translation": "Làm thế nào để bạn đọc xong cuốn sách tôi cho bạn mượn vâng Tôi đã đọc xong nó ngày hôm qua nên nó thú vị không thực sự nó không thú vị và nó chắc chắn cũng không nhàm chán ồ được rồi bạn nghĩ sao về nó Tôi thấy nó khá thú vị Tôi đã học được rất nhiều điều từ nó", "question_vi": "Cô ấy nghĩ gì về cuốn sách?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q45.mp3"}, {"id": 46, "question": "What does the man enjoy most about business trips?", "options": [{"key": "A", "text": "Learn new ideas"}, {"key": "B", "text": "Meet business partners"}, {"key": "C", "text": "A break from the usual daily routine"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/c/_/c_u_247-_what_does_the_man_enjoy_most_about_business_trips.mp3", "transcript": "I travel quite a lot for work and business trips can sometimes be tiring of course I enjoy meeting business partners and getting away from my normal routine for a few days but what I like most is learning new ideas from people in different companies I often come home with a fresh way of thinking", "translation": "Tôi đi công tác khá nhiều và những chuyến công tác đôi khi có thể mệt mỏi, tất nhiên là tôi thích gặp gỡ các đối tác kinh doanh và thoát khỏi công việc thường ngày trong vài ngày nhưng điều tôi thích nhất là học hỏi những ý tưởng mới từ những người ở các công ty khác nhau. Tôi thường về nhà với một lối suy nghĩ mới mẻ", "question_vi": "Người đàn ông thích điều gì nhất trong những chuyến công tác?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q46.mp3"}, {"id": 47, "question": "Listen to a man calling his friend. Why does he make the call?", "options": [{"key": "A", "text": "Telling her he will be late"}, {"key": "B", "text": "Asking for directions"}, {"key": "C", "text": "Inviting her out"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/c/_/c_u_248-_listen_to_a_man_calling_his_friend._why_does_he_make_the_call.mp3", "transcript": "Hi Sarah it's Tom I'm on my way to meet you now but the traffic is much worse than I expected I know where the restaurant is so I don't need any directions I just wanted to let you know that I'll probably arrive about 15 minutes late sorry about that", "translation": "Xin chào Sarah, đây là Tom. Tôi đang trên đường gặp bạn nhưng giao thông tệ hơn tôi tưởng. Tôi biết nhà hàng ở đâu nên tôi không cần chỉ đường. Tôi chỉ muốn cho bạn biết rằng có thể tôi sẽ đến muộn khoảng 15 phút, xin lỗi về điều đó", "question_vi": "Hãy lắng nghe một người đàn ông gọi bạn mình. Tại sao anh ấy lại gọi điện?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q47.mp3"}, {"id": 48, "question": "When will the parent and teacher meeting take place?", "options": [{"key": "A", "text": "Monday"}, {"key": "B", "text": "Friday"}, {"key": "C", "text": "Wednesday"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/c/_/c_u_249-_when_will_the_parent_and_teacher_meeting_take_place.mp3", "transcript": "Just a quick reminder about the parent and teacher meeting we first planned to hold it on Wednesday but several teachers are unavailable that day Friday was also considered but the school hall is being used then so the meeting has been moved to Monday evening at 6:00", "translation": "Xin nhắc lại nhanh về cuộc họp phụ huynh và giáo viên mà lần đầu tiên chúng tôi dự định tổ chức vào thứ Tư nhưng một số giáo viên không có mặt vào ngày hôm đó Thứ Sáu cũng được xem xét nhưng hội trường trường đang được sử dụng nên cuộc họp đã được chuyển sang tối Thứ Hai lúc 6:00", "question_vi": "Khi nào cuộc họp phụ huynh và giáo viên sẽ diễn ra?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q48.mp3"}, {"id": 49, "question": "Why did the woman move abroad?", "options": [{"key": "A", "text": "Improve her career prospects"}, {"key": "B", "text": "Be closer to her family"}, {"key": "C", "text": "Get a higher salary"}], "answer": "B", "url": "https://api.maihienenglish.com.vn/media/file_exercise/c/_/c_u_250-_why_did_the_woman_move_abroad.mp3", "transcript": "A lot of people thought I moved abroad because I wanted a better job and a higher salary those were certainly possible benefits but they weren't my main reason my parents and my older sister had already been living there for several years and I really wanted to be closer to my family", "translation": "Rất nhiều người nghĩ rằng tôi chuyển ra nước ngoài vì tôi muốn có một công việc tốt hơn và mức lương cao hơn, đó chắc chắn là những lợi ích có thể có nhưng đó không phải là lý do chính khiến bố mẹ và chị gái tôi đã sống ở đó được vài năm và tôi thực sự muốn được gần gũi hơn với gia đình mình", "question_vi": "Tại sao người phụ nữ lại chuyển ra nước ngoài?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q49.mp3"}, {"id": 50, "question": "What do they need to repair for the building?", "options": [{"key": "A", "text": "Windows"}, {"key": "B", "text": "Gate"}, {"key": "C", "text": "Doors"}], "answer": "A", "url": "https://api.maihienenglish.com.vn/media/file_exercise/c/_/c_u_251-_what_do_they_need_to_repair_for_the_building.mp3", "transcript": "We checked the building yesterday to see what still needs fixing the main doors are working well and the gate was repaired last month the only real problem is with several windows on the second floor some of them won't close properly so we need to repair those as soon as possible", "translation": "Chúng tôi đã kiểm tra tòa nhà ngày hôm qua để xem những gì vẫn cần sửa. Cửa chính đang hoạt động tốt và cổng đã được sửa chữa vào tháng trước, vấn đề thực sự duy nhất là một số cửa sổ trên tầng hai, một số cửa sổ không đóng đúng cách nên chúng tôi cần sửa chữa chúng càng sớm càng tốt", "question_vi": "Họ cần sửa chữa gì cho tòa nhà?", "answer_guess": true, "audio": "data/Aptis_Listening_Part1.5/audio/q50.mp3"}]};
